
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_gga_x_s12g_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("gga_x_s12g", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-4.342916138011199e+00, -4.257143061418136e+00, -4.137185177150729e+00, -3.971534344782998e+00, -3.747022985044023e+00, -3.451109101601524e+00, -3.077250247461899e+00, -2.634136618869603e+00, -2.150313252867854e+00, -1.646088419364555e+00, -1.109756343663355e+00, -7.204596950440255e-01, -6.129658088657713e-01, -5.017719285020591e-01, -3.737312080174057e-01, -2.495183415355061e-01, -1.341480055553306e-01, -4.849466778262834e-02, -1.053309056765989e-02, -1.184520324428456e-03]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


